#include <bits/stdc++.h>

using namespace std;

int n;

void answer (int a) {
	cout << "! " << a << endl;
} 

int query (int a, int b) {
	cout << "? " << a << " " << b << endl;
	int r;
	cin >> r;
	if (r == -1)
		exit(0);
	return r;
}

void main_ () {
	cin >> n;

	if (n == -1)
	    exit(0);

	if (n == 3) {
	    if (query(1, 2) != query(2, 1)) {
	        if (query(1, 3) != query(3, 1)) {
	            answer(1);
	        } else {
	            answer(2);
	        }
	    } else {
	        answer(3);
	    }
	    return;
	}

	for (int i = 1; i + 1 <= n; i += 2) {
		if (n % 2 == 1 && i == n - 4)
			break;

		if ((n % 2 == 0 && i + 1 == n) || query(i, i + 1) != query(i + 1, i)) {
			int k = 1;
			while (k == i || k == i + 1)
				k++;

			if (query(i, k) != query(k, i)) {
				return answer(i);
			} else {
				return answer(i + 1);
			}
		}
	}

	vector<int> v = {
		query(n - 4, n - 3),
		query(n - 3, n - 2),
		query(n - 2, n - 4)
	};

	if ((v[0] + v[1] + v[2]) % 2 == 0) {
		if (query(n - 3, n - 4) != v[0]) {
			if (query(n - 2, n - 3) != v[1]) {
				answer(n - 3);
			} else {
				answer(n - 4);
			}
		} else {
			answer(n - 2);
		}
	} else {
		if (query(n, 1) != query(1, n)) {
			answer(n);
		} else {
			answer(n - 1);
		}
	}
}

int main () {

	int t;
	cin >> t;

	while (t--)
		main_();

	return 0;
}
